public class LogActionFilter : ActionFilterAttribute
{
    private readonly ILogger<LogActionFilter> _logger;

    public LogActionFilter(ILogger<LogActionFilter> logger)
    {
        _logger = logger;
    }

    public override void OnActionExecuting(ActionExecutingContext context)
    {
        _logger.LogInformation(
            "Executing {Action}",
            context.ActionDescriptor.DisplayName);
        base.OnActionExecuting(context);
    }

    public override void OnActionExecuted(ActionExecutedContext context)
    {
        _logger.LogInformation("Executed {Action}",
            context.ActionDescriptor.DisplayName);
        base.OnActionExecuted(context);
    }
}

// Program.cs - Global registration
builder.Services.AddControllers(options =>
{
    options.Filters.Add<LogActionFilter>();
    options.Filters.Add(new ValidateModelAttribute());
});

// Or per controller
[ServiceFilter(typeof(LogActionFilter))]
public class ProductsController : ControllerBase
{
    [HttpGet]
    [ServiceFilter(typeof(CacheFilter))]
    public IActionResult Get() => Ok("data");
}

// Or per action with TypeFilter
[TypeFilter(typeof(CacheFilter), Arguments = new object[] { 60 })]
public IActionResult GetCached() => Ok("cached");
